import networkx


def get_graph_edges(graph: networkx.Graph) -> list[tuple] | dict[str, list]:
    """Returns a view of all edges in the graph. graph: A NetworkX graph object -> list of edge tuples or dict with edge data."""
    try:
        edges_view = graph.edges()
        # Convert EdgeView to list of tuples for JSON serialization
        return list(edges_view)
    except Exception as e:
        raise ValueError(f"Failed to retrieve edges from graph: {str(e)}")
