import networkx as nx


def create_petersen_graph(create_using: object | None = None) -> dict[str, object]:
    """Creates the Petersen Graph, a well-known symmetric graph with 10 vertices and 15 edges. create_using: Graph type to create. If graph instance, then cleared before populated. -> Graph as dictionary representation."""
    try:
        graph = nx.petersen_graph(create_using=create_using)
        return {
            "name": graph.name,
            "nodes": list(graph.nodes()),
            "edges": list(graph.edges()),
            "number_of_nodes": graph.number_of_nodes(),
            "number_of_edges": graph.number_of_edges()
        }
    except Exception as e:
        raise ValueError(f"Failed to create Petersen Graph: {str(e)}")
